-- 015 · Catálogo de cartas (88). Se puede volver a ejecutar: actualiza las que ya existen.
-- Cantidades en millones. Pesos: común 6 · medio 4 · raro 2 · legendario 1 · choque 4 · entre clubes 2.

insert into public.card_events (id, deck, faction, rarity, weight, icon, text, effect) values
-- ── La Fede ──
('fede-01','suerte','fede','comun',6,'money',$t$La Fede cobra la cuota de «seguridad» al quiosco del estadio. El quiosquero paga en chicles y en un dedo.$t$,'{"t":"self","a":1}'),
('fede-02','suerte','fede','comun',6,'gavel',$t$Un árbitro de la Fede pita un penalti a vuestro favor en un partido que no jugabais. Las apuestas pagan igual.$t$,'{"t":"self","a":2}'),
('fede-03','suerte','fede','comun',6,'money',$t$Colecta para la viuda de un chivato. La viuda no existe; la colecta, sí.$t$,'{"t":"self","a":2}'),
('fede-04','suerte','fede','comun',6,'stadium',$t$El capo os da la concesión de los bocadillos del estadio. Nadie pregunta de qué son.$t$,'{"t":"self","a":3}'),
('fede-05','suerte','fede','comun',6,'coffin',$t$Flores para el entierro de un testigo. Es el cuarto este mes y la floristería ya os hace precio de socio.$t$,'{"t":"self","a":-1}'),
('fede-06','suerte','fede','comun',6,'stadium',$t$Un sobrino del capo entra gratis al palco con 40 amigos y una cabra. La cabra se come las butacas.$t$,'{"t":"self","a":-2}'),
('fede-07','suerte','fede','comun',6,'briefcase',$t$El abogado de la Fede cobra por pasarse por el vestuario a recordar que nadie ha visto nada.$t$,'{"t":"self","a":-2}'),
('fede-08','suerte','fede','comun',6,'coffin',$t$Sube el precio del hormigón para los pies de los soplones. La inflación no respeta ni a la mafia.$t$,'{"t":"self","a":-3}'),
('fede-09','suerte','fede','medio',4,'gavel',$t$La Fede amaña el sorteo de la copa y os toca la CEFA. Las casas de apuestas ni lo cotizan, salvo la vuestra.$t$,'{"t":"self","a":4}'),
('fede-10','suerte','fede','medio',4,'money',$t$Blanqueáis el dinero de la Fede lavando las camisetas. Ahora todo está limpio menos la conciencia.$t$,'{"t":"self","a":5}'),
('fede-11','suerte','fede','medio',4,'coffin',$t$La Fede vende los derechos de imagen de vuestro portero muerto. Le va mejor que vivo.$t$,'{"t":"self","a":6}'),
('fede-12','suerte','fede','medio',4,'briefcase',$t$Una auditoría interna de la Fede descubre que le robabais a la Fede. Os cobran y os dejan vivir, de momento.$t$,'{"t":"self","a":-4}'),
('fede-13','suerte','fede','medio',4,'gavel',$t$Un juez que no cena con la Fede os multa. Ya lo han encontrado, pero la multa sigue puesta.$t$,'{"t":"self","a":-5}'),
('fede-14','suerte','fede','medio',4,'cake',$t$Os toca pagar la boda de la hija del capo: 800 invitados, 3 tiroteos y una tarta con forma de cabeza de la Antifede.$t$,'{"t":"self","a":-6}'),
('fede-15','suerte','fede','raro',2,'money',$t$Muere el capo y os deja en herencia «lo de debajo del césped». Son lingotes y dos señores.$t$,'{"t":"self","a":7}'),
('fede-16','suerte','fede','raro',2,'briefcase',$t$La Fede compra la liga a través de una empresa pantalla. Os toca comisión por firmar sin leer.$t$,'{"t":"self","a":10}'),
('fede-17','suerte','fede','raro',2,'phone',$t$Un chivato de la Fede canta en directo en la tele. Pagáis a un cantante de verdad para que tape su voz.$t$,'{"t":"self","a":-7}'),
('fede-18','suerte','fede','raro',2,'money',$t$La Antifede encuentra vuestra caja B y la dona a una ONG. La ONG también era de la Fede, pero de otra familia.$t$,'{"t":"self","a":-10}'),
('fede-19','suerte','fede','legendario',1,'crown',$t$Vuestro presidente es coronado capo di tutti capi. La coronación se paga sola con lo que «donan» los demás.$t$,'{"t":"self","a":15}'),
('fede-20','suerte','fede','legendario',1,'coffin',$t$Guerra de familias dentro de la Fede. Ganáis, pero os toca pagar los funerales de los dos bandos.$t$,'{"t":"self","a":-15}'),
-- ── La Antifede ──
('anti-01','suerte','antifede','comun',6,'fire',$t$Vendéis camisetas de «Muerte a la Fede». En la Fede también las compran, para quemarlas.$t$,'{"t":"self","a":1}'),
('anti-02','suerte','antifede','comun',6,'money',$t$Atracáis la máquina de refrescos de la sede de la Fede. Dentro había un contable.$t$,'{"t":"self","a":2}'),
('anti-03','suerte','antifede','comun',6,'fire',$t$Un aficionado deja su herencia a la causa. Murió fabricando una bengala casera, pero murió feliz.$t$,'{"t":"self","a":2}'),
('anti-04','suerte','antifede','comun',6,'phone',$t$Crowdfunding para «sabotear el sistema». La plataforma se sabotea sola, pero el dinero llega.$t$,'{"t":"self","a":3}'),
('anti-05','suerte','antifede','comun',6,'bus',$t$Vuestra bengala casera explota en el autobús del club. El conductor ahora es anarquista y cobra plus de peligrosidad.$t$,'{"t":"self","a":-1}'),
('anti-06','suerte','antifede','comun',6,'bird',$t$Fianza del capo de vuestra grada, detenido por intentar secuestrar una paloma de la Fede.$t$,'{"t":"self","a":-2}'),
('anti-07','suerte','antifede','comun',6,'money',$t$El manifiesto del club sale impreso en pan de oro por error. El que lo encargó ya no está entre nosotros.$t$,'{"t":"self","a":-2}'),
('anti-08','suerte','antifede','comun',6,'stadium',$t$Atacáis un estadio de la Fede y resulta que era el vuestro. Toca pagar los cristales.$t$,'{"t":"self","a":-3}'),
('anti-09','suerte','antifede','medio',4,'bomb',$t$Revendéis los explosivos que sobraron de la última revolución. El comprador era de la Fede; la ironía no paga, ellos sí.$t$,'{"t":"self","a":4}'),
('anti-10','suerte','antifede','medio',4,'phone',$t$Un documental sobre vuestro club gana un premio. El jurado lo vio como comedia.$t$,'{"t":"self","a":5}'),
('anti-11','suerte','antifede','medio',4,'stadium',$t$Okupáis el palco de un club de la Fede y alquiláis las butacas por Airbnb.$t$,'{"t":"self","a":6}'),
('anti-12','suerte','antifede','medio',4,'gavel',$t$La policía registra el vestuario y se lo lleva todo. Hasta los conos, «por si acaso».$t$,'{"t":"self","a":-4}'),
('anti-13','suerte','antifede','medio',4,'phone',$t$Vuestra radio pirata se cuela en la frecuencia de la Fede. Os denuncian, y encima la canción era malísima.$t$,'{"t":"self","a":-5}'),
('anti-14','suerte','antifede','medio',4,'briefcase',$t$Os había infiltrado un agente de la Fede: tres años en el equipo y el mejor lateral que habéis tenido. Toca pagarle el finiquito.$t$,'{"t":"self","a":-6}'),
('anti-15','suerte','antifede','raro',2,'crown',$t$Secuestráis el trofeo de liga y pedís rescate. La Fede paga porque el trofeo era falso y no quiere que se sepa.$t$,'{"t":"self","a":7}'),
('anti-16','suerte','antifede','raro',2,'money',$t$Un millonario excéntrico financia la revolución. Cree que sois una secta de donuts.$t$,'{"t":"self","a":10}'),
('anti-17','suerte','antifede','raro',2,'stadium',$t$El túnel hasta la caja de la Fede desemboca en vuestro propio vestuario. Hay que tapar el agujero y comprar taquillas nuevas.$t$,'{"t":"self","a":-7}'),
('anti-18','suerte','antifede','raro',2,'stadium',$t$La Fede compra vuestro estadio y os cobra alquiler por jugar en él. Lo peor es que pagáis puntuales.$t$,'{"t":"self","a":-10}'),
('anti-19','suerte','antifede','legendario',1,'fire',$t$La revolución triunfa durante 48 horas. Saqueáis la sede de la Fede antes de que todo vuelva a la normalidad.$t$,'{"t":"self","a":15}'),
('anti-20','suerte','antifede','legendario',1,'bomb',$t$La gran operación contra la Fede vuela la sede equivocada: la vuestra. Toca reconstruirla entera.$t$,'{"t":"self","a":-15}'),
-- ── La CEFA ──
('cefa-01','suerte','cefa','comun',6,'stadium',$t$Alguien se equivoca de estadio y compra entradas para Charly's. No se atreve a pedir la devolución.$t$,'{"t":"self","a":1}'),
('cefa-02','suerte','cefa','comun',6,'money',$t$La Fede y la Antifede negocian en vuestro campo porque es «territorio neutral». Les cobráis el café.$t$,'{"t":"self","a":2}'),
('cefa-03','suerte','cefa','comun',6,'money',$t$Una ONG os adopta como causa perdida. Os manda dinero y un psicólogo, que dimite el primer día.$t$,'{"t":"self","a":2}'),
('cefa-04','suerte','cefa','comun',6,'phone',$t$Vendéis la exclusiva de vuestras desgracias a un programa de la tele. Es líder de audiencia.$t$,'{"t":"self","a":3}'),
('cefa-05','suerte','cefa','comun',6,'cake',$t$Fiesta de cumpleaños del club y no va nadie. Pagáis la tarta y a un payaso que llora.$t$,'{"t":"self","a":-1}'),
('cefa-06','suerte','cefa','comun',6,'fire',$t$La Fede y la Antifede se pegan en vuestro estadio. Los daños os tocan a vosotros, por poner el sitio.$t$,'{"t":"self","a":-2}'),
('cefa-07','suerte','cefa','comun',6,'phone',$t$Ni la Fede ni la Antifede os cogen el teléfono. Os gastáis la factura en averiguar si os tienen bloqueados.$t$,'{"t":"self","a":-2}'),
('cefa-08','suerte','cefa','comun',6,'bus',$t$Os roban el autobús y nadie pide rescate. Lo volvéis a comprar en el desguace.$t$,'{"t":"self","a":-3}'),
('cefa-09','suerte','cefa','medio',4,'crown',$t$La CEFA se declara país independiente y pide ayudas a Europa. El dinero llega antes de que se den cuenta.$t$,'{"t":"self","a":4}'),
('cefa-10','suerte','cefa','medio',4,'money',$t$Charly's ficha a un mago para el banquillo. Hace desaparecer las deudas y a dos acreedores.$t$,'{"t":"self","a":5}'),
('cefa-11','suerte','cefa','medio',4,'crown',$t$Una fundación premia la «resiliencia» del club. Es el premio que se da cuando no se presenta nadie más.$t$,'{"t":"self","a":6}'),
('cefa-12','suerte','cefa','medio',4,'briefcase',$t$Intentáis entrar en la Fede. La cuota de entrada no se devuelve y la respuesta es no.$t$,'{"t":"self","a":-4}'),
('cefa-13','suerte','cefa','medio',4,'bomb',$t$Intentáis entrar en la Antifede. Pagáis el carné, la boina y el examen de acceso, y suspendéis.$t$,'{"t":"self","a":-5}'),
('cefa-14','suerte','cefa','medio',4,'gavel',$t$La CEFA demanda a la liga por discriminación. El juez se ríe tanto que os condena en costas.$t$,'{"t":"self","a":-6}'),
('cefa-15','suerte','cefa','raro',2,'phone',$t$La Fede y la Antifede os pagan a la vez por espiar a la otra. No espiáis a nadie y nadie se da cuenta.$t$,'{"t":"self","a":7}'),
('cefa-16','suerte','cefa','raro',2,'money',$t$Ganáis el Bote de la Lástima, el fondo secreto de la liga para el club más solo. Nadie más cumplía los requisitos.$t$,'{"t":"self","a":10}'),
('cefa-17','suerte','cefa','raro',2,'cake',$t$Congreso anual de la CEFA. Solo viene Charly's, pero el catering era para 300.$t$,'{"t":"self","a":-7}'),
('cefa-18','suerte','cefa','raro',2,'stadium',$t$Cae un ciclón solo sobre vuestro estadio. Los meteorólogos dicen que ni el tiempo os quiere.$t$,'{"t":"self","a":-10}'),
('cefa-19','suerte','cefa','legendario',1,'crown',$t$La Fede y la Antifede se destruyen mutuamente en una noche. Por la mañana, la CEFA es lo único en pie y vende los escombros.$t$,'{"t":"self","a":15}'),
('cefa-20','suerte','cefa','legendario',1,'coffin',$t$El club entra en bancarrota emocional. Contratáis a todos los psicólogos del país, que también acaban deprimidos.$t$,'{"t":"self","a":-15}'),
-- ── Choques: la Fede ──
('choque-fede-1','cajab','fede','choque',4,'money',$t$Cobro del «impuesto de protección». Nadie sabe de qué protege, pero el último que no pagó juega ahora de central en el fondo del puerto.$t$,'{"t":"rival","f":"antifede","a":3}'),
('choque-fede-2','cajab','fede','choque',4,'briefcase',$t$La Antifede secuestra a tu presidente y lo devuelve a trozos, pero bien ordenados. Pagas el rescate y el pegamento.$t$,'{"t":"rival","f":"antifede","a":-3}'),
('choque-fede-3','cajab','fede','choque',4,'coffin',$t$El capo exige su parte. El que no paga se despierta con una cabeza de caballo en la cama, en gráficos del PES 6 pero igual de desagradable.$t$,'{"t":"mates","per":-2}'),
('choque-fede-4','cajab','fede','choque',4,'crown',$t$Te ascienden a consigliere. Los otros dos clubes de la Fede pagan la fiesta sonriendo con los dientes apretados.$t$,'{"t":"mates","per":2}'),
('choque-fede-5','cajab','fede','choque',4,'money',$t$La Fede obliga a la CEFA a pagar una tasa por existir. Charly's paga y pide recibo. La Fede se ríe durante veinte minutos.$t$,'{"t":"rival","f":"cefa","a":3}'),
('choque-fede-6','cajab','fede','choque',4,'coffin',$t$La Fede pierde una partida de mus contra la CEFA. Nadie en la Fede volverá a hablar de esto, y el testigo tampoco.$t$,'{"t":"rival","f":"cefa","a":-3}'),
-- ── Choques: la Antifede ──
('choque-anti-1','cajab','antifede','choque',4,'bus',$t$Atracáis el furgón de la Fede disfrazados de mascotas. El que iba de oso sigue atrapado en el traje, pero el dinero llegó.$t$,'{"t":"rival","f":"fede","a":3}'),
('choque-anti-2','cajab','antifede','choque',4,'bomb',$t$El plan para volar la sede de la Fede falla: el detonador era un mando de PS2 sin pilas. La Fede os cobra la multa y las pilas.$t$,'{"t":"rival","f":"fede","a":-3}'),
('choque-anti-3','cajab','antifede','choque',4,'fire',$t$Asamblea de la Antifede: se vota por unanimidad que pagues tú la gasolina de la revolución. Votaste a favor y no sabes por qué.$t$,'{"t":"mates","per":-2}'),
('choque-anti-4','cajab','antifede','choque',4,'bird',$t$Tus compañeros de revolución te hacen una colecta para explosivos. Te lo gastas en un loro que grita «muerte a la Fede».$t$,'{"t":"mates","per":2}'),
('choque-anti-5','cajab','antifede','choque',4,'money',$t$Intentáis reclutar a Charly's por decimoquinta vez. Os paga 3M para que paréis.$t$,'{"t":"rival","f":"cefa","a":3}'),
('choque-anti-6','cajab','antifede','choque',4,'bomb',$t$Vuestro artefacto explota en el estadio de Charly's, que ni siquiera era el objetivo. Pagáis los daños y una carta de disculpa que nadie lee.$t$,'{"t":"rival","f":"cefa","a":-3}'),
-- ── Choques: la CEFA ──
('choque-cefa-1','cajab','cefa','choque',4,'briefcase',$t$La Fede le deja un maletín a Charly's para que lo guarde. Charly's se lo gasta, y la Fede no puede denunciar un maletín que oficialmente no existe.$t$,'{"t":"rival","f":"fede","a":3}'),
('choque-cefa-2','cajab','cefa','choque',4,'money',$t$La Fede cobra a la CEFA el impuesto de respirar. Charly's prueba a respirar menos para pagar menos. No cuela.$t$,'{"t":"rival","f":"fede","a":-3}'),
('choque-cefa-3','cajab','cefa','choque',4,'stadium',$t$La Antifede usa el campo de Charly's como polígono de pruebas. Pagan el alquiler, las ventanas y al jardinero, que ahora oye colores.$t$,'{"t":"rival","f":"antifede","a":3}'),
('choque-cefa-4','cajab','cefa','choque',4,'bird',$t$La Antifede secuestra la mascota de la CEFA. Pagáis el rescate y os devuelven otra mascota, peor.$t$,'{"t":"rival","f":"antifede","a":-3}'),
('choque-cefa-5','cajab','cefa','choque',4,'cake',$t$Día Internacional de la CEFA: todos los clubes pagan 1M por lástima. Nadie va a la celebración.$t$,'{"t":"all","per":1}'),
('choque-cefa-6','cajab','cefa','choque',4,'cake',$t$Charly's organiza una cena de hermandad y no va nadie. Manda la comida a cada club con una nota: «Tampoco quería».$t$,'{"t":"all","per":-1}'),
-- ── Entre clubes (a cualquiera) ──
('clubes-01','cajab',null,'clubes',2,'stadium',$t$Tu jardinero, que trabaja en negro para la Fede y para la Antifede a la vez, les envenena el césped. Pagas tú, porque en nómina es tuyo.$t$,'{"t":"rival","f":null,"a":-3}'),
('clubes-02','cajab',null,'clubes',2,'gavel',$t$Ganáis el juicio por plagio de celebración en el tribunal de la Fede. Su delantero queda condenado a celebrar vuestros goles.$t$,'{"t":"rival","f":null,"a":3}'),
('clubes-03','cajab',null,'clubes',2,'coffin',$t$La funeraria oficial de la Fede cambia de patrocinio: dice que vuestra afición tiene más clientes potenciales.$t$,'{"t":"rival","f":null,"a":4}'),
('clubes-04','cajab',null,'clubes',2,'phone',$t$Os roban el patrocinador. Le enseñaron una foto de vuestro presidente con un capo de la Fede y una cabra.$t$,'{"t":"rival","f":null,"a":-4}'),
('clubes-05','cajab',null,'clubes',2,'money',$t$Tu presidente pierde un pulso en la cumbre anual de facciones, y un brazo. Paga la apuesta y la prótesis.$t$,'{"t":"rival","f":null,"a":-2}'),
('clubes-06','cajab',null,'clubes',2,'money',$t$Tu presidente gana al suyo al mus en la cumbre anual de facciones. Se apostó la cartera y a la suegra, y os quedáis con la cartera.$t$,'{"t":"rival","f":null,"a":2}'),
('clubes-07','cajab',null,'clubes',2,'gavel',$t$Impuesto de solidaridad: la Fede dice que os sobra dinero, y la Fede nunca se equivoca. Ni siendo de la Fede se le dice que no.$t$,'{"t":"all","per":-1}'),
('clubes-08','cajab',null,'clubes',2,'phone',$t$Telemaratón benéfico: el club cuenta sus desgracias en directo y las tres facciones lloran a la vez, por primera vez en la historia.$t$,'{"t":"all","per":1}'),
('clubes-09','cajab',null,'clubes',2,'gavel',$t$El líder pierde el juicio ante el tribunal de la Fede por robaros un fichaje que resultó ser un maniquí.$t$,'{"t":"leader","a":3}'),
('clubes-10','cajab',null,'clubes',2,'gavel',$t$El último te demanda ante el tribunal de la Fede por daños morales: dice que tu fútbol quita años de vida. El juez es su primo.$t$,'{"t":"last","a":-3}')
on conflict (id) do update set
  deck = excluded.deck, faction = excluded.faction, rarity = excluded.rarity, weight = excluded.weight,
  icon = excluded.icon, text = excluded.text, effect = excluded.effect;
